[[3, 3, 3], [2, 2, 2]] def transform(grid):
    counts = {3: 0, 2: 0}
    for row in grid:
        for color in (3, 2):
            inside = False
            for value in row:
                if value == color and not inside:
                    counts[color] += 1
                    inside = True
                elif value != color:
                    inside = False
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]
